import { TReadOnlyProperty } from '../../axon/js/TReadOnlyProperty.js';
export declare const writableIsSettingPhetioStateProperty: TinyProperty<boolean>;
declare const isSettingPhetioStateProperty: TReadOnlyProperty<boolean>;
export default isSettingPhetioStateProperty;
